script:
(function () {
  'use strict';
  // Motorcycle loan: monthly payment from the bike's price, or the price a monthly budget covers.
  //   Purchase = bike price + freight/setup + gear and accessories added to the deal.
  //   Taxable amount = purchase - trade-in value (when the trade-in credit box is ticked), never below 0.
  //   Loan = purchase - rebate - down payment - trade-in + owed on trade-in
  //          (+ sales tax and title/registration/doc fees when they are financed).
  //   Payment: M = L x i / (1 - (1 + i)^-n), i = APR / 12, n = months (M = L / n at 0%).
  //   Price mode: L = M(1 - (1 + i)^-n) / i, then the price that produces that loan is found by
  //   bisection (the loan rises steadily with the price).
  // Verified in Node (scratchpad tests/b3auto): $14,000 bike + $650 freight, 6% tax, $300 fees,
  //   $1,500 down, 9% for 60 months -> loan $14,329.00, $297.45/mo, total interest $3,517.79
  //   (closed form PMT x n - L); price mode on $297.45 returns $14,000.00; $12,000 at 0% for 48 months
  //   = $250/mo; no NaN or Infinity on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function loanFromPayment(pmt, annualRate, months) {
    var i = annualRate / 12;
    if (i === 0) return pmt * months;
    return pmt * (1 - Math.pow(1 + i, -months)) / i;
  }

  // Everything that depends on the bike's price.
  function costs(price, o) {
    var purchase = price + o.freight + o.gear;
    var tax = Math.max(0, purchase - (o.tradeCredit ? o.trade : 0)) * o.taxRate / 100;
    var loan = purchase - o.rebate - o.down - o.trade + o.owed + (o.finance ? tax + o.fees : 0);
    return { price: price, purchase: purchase, tax: tax, loan: loan };
  }

  // Bike price whose loan equals the target, by bisection. NaN when even a $0 bike needs a bigger loan.
  function priceForLoan(target, o) {
    if (costs(0, o).loan > target) return NaN;
    var lo = 0, hi = 1;
    while (costs(hi, o).loan < target && hi < 1e10) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (costs(mid, o).loan < target) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function amortize(loan, annualRate, months) {
    var pay = monthlyPayment(loan, annualRate, months);
    var i = annualRate / 12, bal = loan, rows = [], totalInterest = 0;
    for (var m = 1; m <= months && bal > 0.005; m++) {
      var interest = bal * i;
      var principal = Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      rows.push({ n: m, interest: interest, principal: principal, balance: bal });
    }
    return { payment: pay, rows: rows, totalInterest: totalInterest };
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['mcMain', 'mcLoan', 'mcInterest', 'mcTotalCost', 'mcPriceOut', 'mcPaymentOut', 'mcOtd', 'mcTax',
     'mcUpfront', 'mcTotalPayments'].forEach(function (id) { setText(id, '–'); });
    el('mcNegative').hidden = true;
    el('mcSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var head = el('mcScheduleHead'), body = el('mcSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var html = [];
    if (el('mcView').value === 'month') {
      head.innerHTML = '<tr><th scope="col">Month</th><th scope="col">Payment</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Balance</th></tr>';
      last.rows.forEach(function (row) {
        html.push('<tr><td>' + row.n + '</td><td>' + money.format(row.principal + row.interest) + '</td><td>' +
          money.format(row.principal) + '</td><td>' + money.format(row.interest) + '</td><td>' + money.format(row.balance) + '</td></tr>');
      });
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Ending balance</th></tr>';
      var p = 0, intr = 0;
      last.rows.forEach(function (row, idx) {
        p += row.principal; intr += row.interest;
        if (row.n % 12 === 0 || idx === last.rows.length - 1) {
          html.push('<tr><td>' + Math.ceil(row.n / 12) + '</td><td>' + money.format(p) + '</td><td>' +
            money.format(intr) + '</td><td>' + money.format(row.balance) + '</td></tr>');
          p = 0; intr = 0;
        }
      });
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var priceMode = el('mcMode').value === 'price';
    el('mcPriceWrap').hidden = priceMode;
    el('mcBudgetWrap').hidden = !priceMode;
    var o = {
      freight: read('mcFreight', true), gear: read('mcGear', true), rebate: read('mcRebate', true),
      down: read('mcDown', true), trade: read('mcTrade', true), owed: read('mcOwed', true),
      taxRate: read('mcTaxRate', true), fees: read('mcFees', true),
      finance: el('mcFinance').checked, tradeCredit: el('mcTradeCredit').checked
    };
    var price = read('mcPrice'), budget = read('mcBudget'), rate = read('mcRate'), months = read('mcTerm');
    var error = el('mcError'), msg = '';
    if (!priceMode && (isNaN(price) || price <= 0)) msg = 'Enter a motorcycle price greater than $0.';
    else if (priceMode && (isNaN(budget) || budget <= 0)) msg = 'Enter a monthly payment greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (isNaN(months) || months < 1 || months > 120 || months % 1 !== 0) msg = 'Enter a loan term of 1 to 120 whole months.';
    else if (['freight', 'gear', 'rebate', 'down', 'trade', 'owed', 'taxRate', 'fees'].some(function (k) { return isNaN(o[k]) || o[k] < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }

    var r = rate / 100, c;
    if (priceMode) {
      var p = priceForLoan(loanFromPayment(budget, r, months), o);
      if (!(p > 0) || !isFinite(p)) msg = 'That payment is too small to cover the costs and trade-in balance you are financing.';
      else c = costs(p, o);
    } else {
      c = costs(price, o);
      if (c.loan <= 0.005) msg = 'Your down payment, rebate and trade-in cover the full cost, so there is nothing to finance.';
    }
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    var a = amortize(c.loan, r, months);
    var upfront = o.down + (o.finance ? 0 : c.tax + o.fees);
    var otd = c.purchase - o.rebate + c.tax + o.fees;
    setText('mcMainLabel', priceMode ? 'Motorcycle price you can afford' : 'Monthly payment');
    setText('mcMain', money.format(priceMode ? c.price : a.payment));
    setText('mcLoan', money.format(c.loan));
    setText('mcInterest', money.format(a.totalInterest));
    setText('mcTotalCost', money.format(otd + a.totalInterest));
    setText('mcPriceOut', money.format(c.price));
    setText('mcPaymentOut', money.format(a.payment));
    setText('mcOtd', money.format(otd));
    setText('mcTax', money.format(c.tax));
    setText('mcUpfront', money.format(upfront));
    setText('mcTotalPayments', money.format(c.loan + a.totalInterest));
    el('mcNegative').hidden = !(o.owed > o.trade);
    setText('mcNegativeAmount', money.format(Math.max(0, o.owed - o.trade)));
    last = { rows: a.rows };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('mcForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('mcView').addEventListener('change', renderSchedule);
    update();
  });
})();
